const s = $('Gym Settings').first().json;
const NL = String.fromCharCode(10);
const DAY = 86400000;
const now = Date.now();
const members = $('Get Active Members').all().map(i => i.json).filter(m => m.member_ref);
const visitsByRef = {};
for (const item of $input.all()) {
  const c = item.json;
  if (!c.member_ref || !c.checked_in_at) continue;
  const t = new Date(c.checked_in_at).getTime();
  if (isNaN(t) || t > now) continue;
  if (!visitsByRef[c.member_ref]) visitsByRef[c.member_ref] = [];
  visitsByRef[c.member_ref].push(t);
}
const round1 = n => Math.round(n * 10) / 10;
const out = [];
for (const m of members) {
  const visits = (visitsByRef[m.member_ref] || []).sort((a, b) => b - a);
  const joined = m.join_date ? new Date(m.join_date).getTime() : NaN;
  const tenure = isNaN(joined) ? null : Math.max(0, Math.floor((now - joined) / DAY));
  const last = visits.length ? visits[0] : null;
  const daysSince = last !== null ? Math.floor((now - last) / DAY) : tenure;
  const v30 = visits.filter(t => now - t <= 30 * DAY).length;
  const vPrev = visits.filter(t => now - t > 30 * DAY && now - t <= 90 * DAY).length;
  const prevDays = tenure === null ? 60 : Math.max(0, Math.min(60, tenure - 30));
  const usual = prevDays >= 14 ? vPrev / (prevDays / 7) : null;
  const recentDays = tenure === null ? 30 : Math.max(7, Math.min(30, tenure));
  const recent = v30 / (recentDays / 7);
  let score = 0;
  const reasons = [];
  if (daysSince !== null) {
    if (daysSince >= 21) { score += 45; reasons.push('No visit in ' + daysSince + ' days'); }
    else if (daysSince >= 14) { score += 35; reasons.push('No visit in ' + daysSince + ' days'); }
    else if (daysSince >= 10) { score += 25; reasons.push('No visit in ' + daysSince + ' days'); }
    else if (daysSince >= 7) { score += 12; reasons.push('No visit in ' + daysSince + ' days'); }
  }
  if (usual !== null && usual >= 1) {
    const usualGap = 7 / usual;
    if (daysSince !== null && daysSince >= 7 && daysSince > usualGap * 3) {
      score += 10;
      reasons.push('Gap is over 3x their usual ' + round1(usualGap) + ' days between visits');
    }
    const drop = 1 - recent / usual;
    const dropText = 'Visits down ' + Math.round(drop * 100) + '% (' + round1(usual) + '/week before, ' + round1(recent) + '/week now)';
    if (drop >= 0.7) { score += 30; reasons.push(dropText); }
    else if (drop >= 0.5) { score += 20; reasons.push(dropText); }
    else if (drop >= 0.3) { score += 10; reasons.push(dropText); }
  }
  if (tenure !== null && tenure <= 60 && v30 < 4) {
    score += 15;
    reasons.push('New member (joined ' + tenure + ' days ago) with only ' + v30 + ' visits in the last 30 days');
  }
  score = Math.min(100, score);
  const level = score >= s.highRiskScore ? 'high' : score >= s.mediumRiskScore ? 'medium' : 'low';
  const lastOutreach = m.last_outreach_at ? new Date(m.last_outreach_at).getTime() : NaN;
  const cooledDown = isNaN(lastOutreach) || (now - lastOutreach) / DAY >= s.outreachCooldownDays;
  const sent = Number(m.outreach_count || 0);
  const needsOutreach = level === 'high' && cooledDown && !!m.email && sent < s.maxOutreachPerMember;
  const firstName = String(m.name || '').trim().split(' ')[0] || 'there';
  const systemPrompt = [
    'You write short, warm win-back emails for ' + s.gymName + ', sent by ' + s.senderName + '.',
    'The member has been coming less often. The goal is to get them back through the door with kindness, never guilt.',
    'Rules:',
    '- Plain text, 60 to 110 words, greet them by first name, sign off as ' + s.senderName + '.',
    '- Mention their routine naturally (for example the sessions they used to do each week or how long they have been a member), in the tone of a coach who noticed they have not been in, not a system that tracked them.',
    '- Never shame, never mention weight, body shape, calories or appearance, never use fake urgency.',
    '- Offer: ' + s.winbackOffer + '.',
    s.bookingLink ? '- Include this booking link once: ' + s.bookingLink : '- Ask them to simply reply to this email to claim it.',
    '- End with one easy next step.',
    'Return only JSON: {"subject": "under 7 words, no emojis", "message": "the email body"}'
  ].join(NL);
  const userPrompt = [
    'Member first name: ' + firstName,
    'Plan: ' + (m.plan || 'unknown'),
    'Member for: ' + (tenure === null ? 'unknown' : tenure + ' days'),
    'Trainer: ' + (m.trainer || 'none'),
    'Usual visits per week before: ' + (usual === null ? 'not enough history' : round1(usual)),
    'Visits in the last 30 days: ' + v30,
    'Days since last visit: ' + (daysSince === null ? 'unknown' : daysSince),
    'Why they were flagged: ' + reasons.join('; ')
  ].join(NL);
  out.push({ json: {
    member_ref: m.member_ref,
    name: m.name || '',
    first_name: firstName,
    email: m.email || '',
    plan: m.plan || '',
    monthly_fee: Number(m.monthly_fee || 0),
    trainer: m.trainer || '',
    tenure_days: tenure,
    last_visit: last !== null ? new Date(last).toISOString() : null,
    days_since_visit: daysSince,
    visits_30d: v30,
    visits_prev_60d: vPrev,
    usual_per_week: usual === null ? null : round1(usual),
    recent_per_week: round1(recent),
    risk_score: score,
    risk_level: level,
    risk_reasons: reasons.join('; '),
    scored_at: new Date(now).toISOString(),
    outreach_count: sent,
    needs_outreach: needsOutreach,
    system_prompt: systemPrompt,
    user_prompt: userPrompt
  } });
}
out.sort((a, b) => b.json.risk_score - a.json.risk_score);
return out;

const s = $('Gym Settings').first().json;
const m = $('Cap Daily Outreach').item.json;
const NL = String.fromCharCode(10);
const r = $json || {};
let text = '';
if (typeof r.merged_response === 'string') text = r.merged_response;
else if (Array.isArray(r.content)) text = r.content.filter(c => c && c.type === 'text').map(c => c.text).join('');
else if (typeof r.content === 'string') text = r.content;
else if (typeof r.text === 'string') text = r.text;
else if (typeof r.output === 'string') text = r.output;
let subject = '';
let message = '';
try {
  const parsed = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  subject = String(parsed.subject || '').trim();
  message = String(parsed.message || '').trim();
} catch (e) {}
const aiWritten = !!(subject && message);
if (!aiWritten) {
  subject = 'We miss you at ' + s.gymName;
  message = [
    'Hi ' + m.first_name + ',',
    '',
    "We haven't seen you at " + s.gymName + ' for a little while and wanted to check in.',
    '',
    'Life gets busy, and restarting is often the hardest part, so we would love to offer you ' + s.winbackOffer + '.',
    '',
    s.bookingLink ? 'Book a time here: ' + s.bookingLink : 'Just reply to this email and we will set it up.',
    '',
    s.senderName
  ].join(NL);
}
const sendTo = s.demoMode ? s.ownerEmail : m.email;
return { json: {
  member_ref: m.member_ref,
  name: m.name,
  email: m.email,
  monthly_fee: m.monthly_fee,
  risk_score: m.risk_score,
  risk_level: m.risk_level,
  risk_reasons: m.risk_reasons,
  outreach_count: Number(m.outreach_count || 0) + 1,
  subject: subject,
  message: message,
  send_to: sendTo,
  send_subject: s.demoMode ? '[DEMO for ' + m.name + '] ' + subject : subject,
  demo_mode: !!s.demoMode,
  ai_written: aiWritten,
  sent_at: new Date().toISOString()
} };

const s = $('Gym Settings').first().json;
const rows = $input.all().map(i => i.json);
const atRisk = rows.filter(r => r.risk_level === 'high' || r.risk_level === 'medium');
if (!atRisk.length) return [];
const esc = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = n => s.currency + Math.round(n).toLocaleString('en-US');
const high = atRisk.filter(r => r.risk_level === 'high');
const revenue = atRisk.reduce((a, r) => a + Number(r.monthly_fee || 0), 0);
const contacted = high.filter(r => r.needs_outreach).length;
const badge = level => level === 'high'
  ? '<span style="background:#fde2e1;color:#b42318;padding:2px 8px;border-radius:10px;font-size:12px;font-weight:600">HIGH</span>'
  : '<span style="background:#fef0c7;color:#b54708;padding:2px 8px;border-radius:10px;font-size:12px;font-weight:600">MEDIUM</span>';
const rowsHtml = atRisk.slice(0, 30).map(r =>
  '<tr>' +
  '<td style="padding:10px 8px;border-bottom:1px solid #eee"><strong>' + esc(r.name) + '</strong><br><span style="color:#667085;font-size:12px">' + esc(r.plan) + ' · ' + esc(r.trainer) + '</span></td>' +
  '<td style="padding:10px 8px;border-bottom:1px solid #eee">' + badge(r.risk_level) + '<br><span style="color:#667085;font-size:12px">score ' + r.risk_score + '</span></td>' +
  '<td style="padding:10px 8px;border-bottom:1px solid #eee;font-size:13px">' + esc(r.risk_reasons) + '</td>' +
  '<td style="padding:10px 8px;border-bottom:1px solid #eee;text-align:right">' + money(r.monthly_fee) + '/mo</td>' +
  '</tr>').join('');
const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;color:#101828">' +
  '<h2 style="margin:0 0 4px">Members at risk today</h2>' +
  '<p style="margin:0 0 16px;color:#667085">' + esc(s.gymName) + ' · Gym Churn Radar</p>' +
  '<table style="width:100%;border-collapse:collapse;margin-bottom:16px"><tr>' +
  '<td style="background:#fef3f2;padding:14px;border-radius:8px;width:33%"><div style="font-size:24px;font-weight:700;color:#b42318">' + high.length + '</div><div style="font-size:12px;color:#667085">high risk</div></td>' +
  '<td style="width:8px"></td>' +
  '<td style="background:#fffaeb;padding:14px;border-radius:8px;width:33%"><div style="font-size:24px;font-weight:700;color:#b54708">' + (atRisk.length - high.length) + '</div><div style="font-size:12px;color:#667085">medium risk</div></td>' +
  '<td style="width:8px"></td>' +
  '<td style="background:#f2f4f7;padding:14px;border-radius:8px;width:33%"><div style="font-size:24px;font-weight:700">' + money(revenue) + '</div><div style="font-size:12px;color:#667085">monthly revenue at risk</div></td>' +
  '</tr></table>' +
  '<p style="font-size:14px">' + contacted + ' high-risk member(s) are getting a personal win-back email this morning' + (s.demoMode ? ' <strong>(demo mode: sent to you, not to members)</strong>' : '') + '. A quick call or a hello from their trainer doubles the effect.</p>' +
  '<table style="width:100%;border-collapse:collapse;font-size:14px"><tr style="text-align:left;color:#667085;font-size:12px"><th style="padding:8px">Member</th><th style="padding:8px">Risk</th><th style="padding:8px">Why</th><th style="padding:8px;text-align:right">Value</th></tr>' + rowsHtml + '</table>' +
  '</div>';
return [{ json: { subject: high.length + ' members at high risk of cancelling · ' + money(revenue) + '/mo at stake', html } }];
